import React, { useState } from 'react';

const navItems = [
  { icon: '📅', label: 'Acara',    href: '#acara-section' },
  { icon: '📍', label: 'Lokasi',   href: '#lokasi-section' },
  { icon: '🎵', label: 'Musik',    center: true },
  { icon: '❤️', label: 'Mempelai', href: '#mempelai-section' },
];

export default function BottomNav() {
  const [active, setActive]   = useState(null);
  const [playing, setPlaying] = useState(false);

  const scrollTo = (href, index) => {
    setActive(index);
    const el = document.querySelector(href);
    if (el) el.scrollIntoView({ behavior: 'smooth' });
  };

  return (
    <>
      <style>{`
        .nav-item-btn {
          background: none;
          border: none;
          cursor: pointer;
          display: flex;
          flex-direction: column;
          align-items: center;
          gap: 4px;
          padding: 8px 4px;
          color: white;
          transition: transform 0.15s;
          flex: 1;
        }
        .nav-item-btn:hover { transform: translateY(-3px); }
        .nav-item-btn.nav-active { transform: translateY(-4px); opacity: 1 !important; }
        .nav-item-btn .icon { font-size: 1.3rem; }
        .nav-item-btn .lbl {
          font-family: 'Poppins', sans-serif;
          font-size: 0.6rem;
          white-space: nowrap;
          opacity: 0.9;
        }
        .center-btn {
          width: 56px;
          height: 56px;
          border-radius: 50%;
          background: #1a1a2e;
          border: 3px solid #2a2a4e;
          display: flex;
          align-items: center;
          justify-content: center;
          cursor: pointer;
          margin-top: -20px;
          box-shadow: 0 4px 15px rgba(0,0,0,0.4);
          transition: transform 0.2s;
        }
        .center-btn:hover { transform: scale(1.1); }
        .disc {
          width: 36px;
          height: 36px;
          border-radius: 50%;
          background: #333;
          border: 2px solid #555;
          display: flex;
          align-items: center;
          justify-content: center;
        }
        .disc-center {
          width: 10px;
          height: 10px;
          border-radius: 50%;
          background: #888;
          border: 1px solid #aaa;
        }
        @keyframes spin {
          from { transform: rotate(0deg); }
          to   { transform: rotate(360deg); }
        }
        .disc-playing { animation: spin 2s linear infinite; }
      `}</style>

      <nav style={{
        position: 'fixed',
        bottom: 0,
        left: 0,
        right: 0,
        background: 'linear-gradient(90deg, #e91e8c, #d41680)',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-around',
        padding: '8px 6px 12px',
        zIndex: 100,
        boxShadow: '0 -4px 20px rgba(233,30,140,0.4)',
      }}>
        {navItems.map((item, i) =>
          item.center ? (
            <button
              key={i}
              className="center-btn"
              onClick={() => setPlaying(p => !p)}
              title={playing ? 'Pause Musik' : 'Putar Musik'}
            >
              <div className={`disc${playing ? ' disc-playing' : ''}`}>
                <div className="disc-center" />
              </div>
            </button>
          ) : (
            <button
              key={i}
              className={`nav-item-btn${active === i ? ' nav-active' : ''}`}
              onClick={() => scrollTo(item.href, i)}
              style={{ opacity: active === i ? 1 : 0.85 }}
            >
              <span className="icon">{item.icon}</span>
              <span className="lbl">{item.label}</span>
            </button>
          )
        )}
      </nav>

      <div style={{ height: '80px' }} />
    </>
  );
}
